import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin {
  /// Базовая валюта проекта, относительно которой запрашиваются курсы.
  static const String _baseCurrency = 'EUR';

  static const int _pageSize = 20;

  static const Duration _pageFetchDelay = Duration(milliseconds: 120);

  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  late final Future<void> _initialLoadFuture;

  List<CurrencyModel> _allCurrencies = [];

  String _query = '';

  int _nextPage = 0;

  bool _hasMore = false;

  bool _isLoadingMore = false;

  bool _isRouteFocused = true;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initialLoadFuture = _loadFirstPage();
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    _isRouteFocused = ModalRoute.of(context)?.isCurrent ?? true;
  }

  @override
  void dispose() {
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  /// Загружает список заново свежим запросом с базовой валютой проекта.
  Future<void> _loadFirstPage() async {
    final currencyRepository = context.read<CurrencyRepository>();

    _nextPage = 0;
    _hasMore = false;

    final CurrencyPage page = await currencyRepository.fetchRates(
      const CurrencyPageRequest(base: _baseCurrency, pageSize: _pageSize),
    );

    if (!mounted) return;

    _nextPage = page.page + 1;
    _hasMore = page.hasMore;

    setState(() => _applyCurrencies(page.items));

    _fadeController.forward(); // запускаем анимацию

    await currencyRepository.saveCurrencyList(page.items);
  }

  Future<void> _showMore() async {
    if (_isLoadingMore || !_hasMore) return;

    setState(() => _isLoadingMore = true);

    final currencyRepository = context.read<CurrencyRepository>();

    try {
      final CurrencyPage page = await currencyRepository.fetchRates(
        CurrencyPageRequest(base: _baseCurrency, page: _nextPage, pageSize: _pageSize),
      );

      if (!mounted) return;

      final List<CurrencyModel> merged = <CurrencyModel>[..._allCurrencies, ...page.items];

      setState(() {
        _nextPage = page.page + 1;
        _hasMore = page.hasMore;
        _applyCurrencies(merged);
      });

      await currencyRepository.saveCurrencyList(merged);
    } finally {
      if (mounted) setState(() => _isLoadingMore = false);
    }
  }

  /// Обновляет отображаемый список без сброса позиции скролла.
  void _applyCurrencies(List<CurrencyModel> currencies) {
    _allCurrencies = currencies;

    final String lowerQuery = _query.toLowerCase();
    _filteredCurrenciesNotifier.value = lowerQuery.isEmpty
        ? List<CurrencyModel>.unmodifiable(currencies)
        : currencies
            .where(
              (CurrencyModel currency) =>
                  currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery),
            )
            .toList(growable: false);
  }

  void _filterCurrencies(String query) {
    _query = query;
    _applyCurrencies(_allCurrencies);
  }

  /// Экран потерял фокус (уход на другой маршрут или вкладку) — список обновляется свежим запросом.
  void _refreshOnFocusLost() {
    if (!_isRouteFocused) return;

    _isRouteFocused = false;

    if (!mounted) return;

    _reload();
  }

  /// Экран снова в фокусе — следующий уход снова вызовет обновление.
  void _onFocusGained() => _isRouteFocused = true;

  void _reload() {
    final Future<void> request = _loadFirstPage();

    // Обновление идёт в фоне, ошибки запроса не должны «зависать» как unhandled.
    unawaited(request.catchError((Object _) {}));
  }

  @override
  Widget build(BuildContext context) {
    return FocusDetector(
      onFocusLost: _refreshOnFocusLost,
      onFocusGained: _onFocusGained,
      child: _CurrencyListContent(
        fadeController: _fadeController,
        initialLoadFuture: _initialLoadFuture,
        filteredCurrenciesNotifier: _filteredCurrenciesNotifier,
        onSearchChanged: _filterCurrencies,
        onShowMore: _showMore,
        hasMoreListenable: _hasMoreListenable,
      ),
    );
  }

  /// [hasMore] и [isLoadingMore] в одном слушателе — кнопка «Показать ещё» перестраивается на оба флага.
  ValueListenable<bool> get _hasMoreListenable => _HasMoreNotifier(
        hasMore: () => _hasMore,
        isLoading: () => _isLoadingMore,
      );
}

class _CurrencyListContent extends StatelessWidget {
  const _CurrencyListContent({
    required this.fadeController,
    required this.initialLoadFuture,
    required this.filteredCurrenciesNotifier,
    required this.onSearchChanged,
    required this.onShowMore,
    required this.hasMoreListenable,
  });

  final AnimationController fadeController;
  final Future<void> initialLoadFuture;
  final ValueListenable<List<CurrencyModel>> filteredCurrenciesNotifier;
  final ValueChanged<String> onSearchChanged;
  final VoidCallback onShowMore;
  final ValueListenable<bool> hasMoreListenable;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder(
        future: initialLoadFuture,
        builder: (BuildContext context, AsyncSnapshot<void> snapshot) {
          return FadeTransition(
            opacity: fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: onSearchChanged),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> data, _) {
                      return ListView.builder(
                        itemCount: data.length,
                        itemBuilder: (BuildContext context, int index) {
                          final CurrencyModel currency = data[index];

                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                        padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                      );
                    },
                  ),
                ),
                ValueListenableBuilder<bool>(
                  valueListenable: hasMoreListenable,
                  builder: (BuildContext context, bool hasMore, _) {
                    if (!hasMore) return const SizedBox.shrink();

                    return Padding(
                      padding: const EdgeInsets.fromLTRB(22, 0, 22, 20),
                      child: ElevatedButton(
                        onPressed: onShowMore,
                        child: Text(
                          context.loc.showMore,
                          style: context.fonts.regular14,
                        ),
                      ),
                    );
                  },
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}

/// Слушатель признака «есть следующая страница» (учитывает и активную догрузку).
class _HasMoreNotifier extends ValueNotifier<bool> {
  _HasMoreNotifier({required bool Function() hasMore, required bool Function() isLoading})
      : _hasMore = hasMore,
        _isLoading = isLoading,
        super(hasMore() && !isLoading());

  final bool Function() _hasMore;
  final bool Function() _isLoading;

  @override
  bool get value => _hasMore() && !_isLoading();

  @override
  set value(bool newValue) => super.value = newValue;
}

