/// Сообщает о потере и возврате фокуса экрана.
///
/// Фокус теряется, когда экран перестаёт быть текущим маршрутом
/// (например, при переходе на экран детализации) или когда приложение
/// уходит в фон.
class FocusDetector extends StatefulWidget {
  const FocusDetector({
    super.key,
    required this.child,
    this.onFocusLost,
    this.onFocusGained,
  });

  final Widget child;

  final VoidCallback? onFocusLost;

  final VoidCallback? onFocusGained;

  @override
  State<FocusDetector> createState() => _FocusDetectorState();
}

class _FocusDetectorState extends State<FocusDetector> with WidgetsBindingObserver {
  ModalRoute<Object?>? _route;

  bool _isFocused = true;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();

    _route?.removeListener(_onRouteChanged);

    final ModalRoute<Object?>? route = ModalRoute.of(context);
    route?.addListener(_onRouteChanged);
    _route = route;

    _updateFocus(isFocused: (route?.isCurrent ?? true) && _isAppActive);
  }

  @override
  void dispose() {
    _route?.removeListener(_onRouteChanged);
    WidgetsBinding.instance.removeObserver(this);
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    _updateFocus(isFocused: (_route?.isCurrent ?? true) && state == AppLifecycleState.resumed);
  }

  bool get _isAppActive {
    final AppLifecycleState? state = WidgetsBinding.instance.lifecycleState;

    return state == null || state == AppLifecycleState.resumed;
  }

  void _onRouteChanged() => _updateFocus(isFocused: _route?.isCurrent ?? true);

  void _updateFocus({required bool isFocused}) {
    if (_isFocused == isFocused) return;

    _isFocused = isFocused;

    if (isFocused) {
      widget.onFocusGained?.call();
    } else {
      widget.onFocusLost?.call();
    }
  }

  @override
  Widget build(BuildContext context) => widget.child;
}

