61:   CurrencyPageRequest _pageRequest(int page) => CurrencyPageRequest(base: _baseCurrency, page: page, pageSize: _pageSize);
62: 
63:   void _initAnimation() {
64:     _fadeController = AnimationController(
65:       duration: Duration(milliseconds: 400),
66:       vsync: this,
67:     );
68:   }
69: 
70:   /// Загружает список заново свежим запросом с базовой валютой проекта.
71:   Future<void> _loadFirstPage() async {
72:     final currencyRepository = context.read<CurrencyRepository>();
73: 
74:     _nextPage = 0;
75:     _hasMore = false;
76: 
77:     final CurrencyPage page = await currencyRepository.fetchRates(_pageRequest(0));
78: 
79:     if (!mounted) return;
80: 
81:     _nextPage = page.page + 1;
82:     _hasMore = page.hasMore;
83: 
84:     setState(() => _applyCurrencies(page.items));
85: 
86:     _fadeController.forward(); // запускаем анимацию
87: 
88:     await currencyRepository.saveCurrencyList(page.items);
89:   }
90: 
91:   Future<void> _showMore() async {
92:     if (_isLoadingMore || !_hasMore) return;
93: 
94:     setState(() => _isLoadingMore = true);
95: 
96:     final currencyRepository = context.read<CurrencyRepository>();
97: 
98:     try {
99:       final CurrencyPage page = await currencyRepository.fetchRates(_pageRequest(_nextPage));
100: 
101:       if (!mounted) return;
102: 
103:       final List<CurrencyModel> merged = <CurrencyModel>[..._allCurrencies, ...page.items];
104: 
105:       setState(() {
106:         _nextPage = page.page + 1;
107:         _hasMore = page.hasMore;
108:         _applyCurrencies(merged);
109:       });
110: 
111:       await currencyRepository.saveCurrencyList(merged);
112:     } finally {
113:       if (mounted) setState(() => _isLoadingMore = false);
114:     }
115:   }
116: 
117:   /// Обновляет отображаемый список без сброса позиции скролла.
118:   void _applyCurrencies(List<CurrencyModel> currencies) {
119:     _allCurrencies = currencies;
120: 
121:     final String lowerQuery = _query.toLowerCase();
122:     _filteredCurrenciesNotifier.value = lowerQuery.isEmpty
123:         ? List<CurrencyModel>.unmodifiable(currencies)
124:         : currencies
125:             .where(
126:               (CurrencyModel currency) =>
127:                   currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery),
128:             )
129:             .toList(growable: false);
130:   }
131: 
132:   void _filterCurrencies(String query) {
133:     _query = query;
134:     _applyCurrencies(_allCurrencies);
135:   }
136: 
137:   /// Экран потерял фокус (уход на другой маршрут или вкладку) — список обновляется свежим запросом.
138:   void _refreshOnFocusLost() {
139:     if (!_isRouteFocused) return;
140: 
141:     _isRouteFocused = false;
142: 
143:     if (!mounted) return;
144: 
145:     _reload();
146:   }
147: 
148:   /// Экран снова в фокусе — следующий уход снова вызовет обновление.
149:   void _onFocusGained() => _isRouteFocused = true;
150: 
151:   void _reload() {
152:     final Future<void> request = _loadFirstPage();
153: 
154:     // Обновление идёт в фоне, ошибки запроса не должны «зависать» как unhandled.
155:     unawaited(request.catchError((Object _) {}));
156:   }
157: 
158:   @override
159:   Widget build(BuildContext context) {
160:     return FocusDetector(
161:       onFocusLost: _refreshOnFocusLost,
162:       onFocusGained: _onFocusGained,
163:       child: _CurrencyListContent(
164:         fadeController: _fadeController,
165:         initialLoadFuture: _initialLoadFuture,
166:         filteredCurrenciesNotifier: _filteredCurrenciesNotifier,
167:         onSearchChanged: _filterCurrencies,
168:         onShowMore: _showMore,
169:         hasMoreListenable: _hasMoreListenable,
170:       ),
171:     );
172:   }
173: 
174:   /// [hasMore] и [isLoadingMore] в одном слушателе — кнопка «Показать ещё» перестраивается на оба флага.
175:   ValueListenable<bool> get _hasMoreListenable => _HasMoreNotifier(
176:         hasMore: () => _hasMore,
177:         isLoading: () => _isLoadingMore,
178:       );
179: }
